content:
// ==UserScript==
// @name         主角跨聊天传承（适配龙血玄黄数据库）
// @namespace    https://github.com/16525678/st-protagonist-carryover
// @version      0.4.0
// @description  从龙血玄黄·数据库导出主角并按目标聊天表规则继承到新聊天（支持酒馆助手 / SillyTavern / TauriTavern 桌面与手机端）
// @author       16525678
// @match        */*
// @grant        none
// ==/UserScript==
(function() {
  'use strict';
  const EMBEDDED_STYLE_CSS = "/* 主角跨聊天传承插件双端样式 — 桌面端 + 手机端（TauriTavern Android/iOS WebView & SillyTavern） */

.pc-lock-scroll {
  overflow: hidden !important;
  overscroll-behavior: none !important;
}

.pc-drawer-status {
  font-size: 0.9em;
  line-height: 1.5;
  margin-bottom: 8px;
  padding: 8px 10px;
  border-radius: 6px;
  background: var(--SmartThemeBlurTintColor, rgba(0, 0, 0, 0.25));
  border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.14));
}

.pc-drawer-line {
  margin-bottom: 3px;
  word-break: break-word;
}

.pc-drawer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 6px;
}

/* 零全屏 backdrop-filter blur，消除手机与桌面 WebView 合成重绘卡顿 */
.pc-overlay {
  position: fixed;
  inset: 0;
  z-index: 9990;
  background: rgba(10, 12, 18, 0.78);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  overscroll-behavior: contain;
}

.pc-modal {
  width: min(1040px, 96vw);
  max-height: 90dvh;
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  overflow: hidden;
  contain: layout paint;
  background: var(--SmartThemeBlurTintColor, #1c1f26);
  color: var(--SmartThemeBodyColor, #e8ecf1);
  border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.18));
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
}

.pc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.14));
  flex-shrink: 0;
}

.pc-title {
  margin: 0;
  font-size: 1.12em;
}

.pc-subtitle {
  display: block;
  font-size: 0.82em;
  opacity: 0.78;
  margin-top: 2px;
}

.pc-close-btn {
  background: transparent;
  border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.2));
  color: inherit;
  border-radius: 8px;
  min-width: 36px;
  min-height: 36px;
  cursor: pointer;
  flex-shrink: 0;
}

.pc-tabs {
  display: flex;
  gap: 4px;
  padding: 8px 16px 0;
  border-bottom: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.14));
  flex-shrink: 0;
}

.pc-tab {
  background: transparent;
  color: inherit;
  border: 1px solid transparent;
  border-bottom: none;
  border-radius: 8px 8px 0 0;
  padding: 9px 14px;
  cursor: pointer;
  opacity: 0.76;
  font-weight: 600;
  white-space: nowrap;
}

.pc-tab.is-active {
  opacity: 1;
  background: rgba(255, 255, 255, 0.09);
  border-color: var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.18));
}

.pc-body {
  padding: 14px 16px;
  overflow-y: auto;
  overflow-x: hidden;
  overflow-anchor: none;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-y;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pc-stack {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pc-card {
  padding: 12px 14px;
  border-radius: 8px;
  contain: layout style;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.14));
}

.pc-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.pc-toolbar-btns {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.pc-file-btn {
  display: inline-flex;
  align-items: center;
  cursor: pointer;
}

.pc-btn-primary {
  font-weight: 600;
  border-color: var(--SmartThemeQuoteColor, #4f8cff) !important;
}

.pc-btn-danger {
  border-color: rgba(235, 87, 87, 0.65) !important;
  color: #ff9c9c !important;
}

.pc-mini-btn {
  background: rgba(255, 255, 255, 0.08);
  color: inherit;
  border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.18));
  border-radius: 6px;
  padding: 4px 10px;
  font-size: 0.85em;
  cursor: pointer;
  white-space: nowrap;
}

.pc-mini-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.pc-checkbox {
  width: 18px;
  height: 18px;
  margin: 0;
  flex-shrink: 0;
  cursor: pointer;
}

.pc-empty {
  text-align: center;
  padding: 26px 14px;
  border-radius: 8px;
  border: 1px dashed var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.2));
}

.pc-muted {
  opacity: 0.76;
  font-size: 0.9em;
}

.pc-section-title {
  font-weight: 700;
  font-size: 0.95em;
  margin-top: 2px;
}

.pc-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.pc-grid-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.pc-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.92em;
}

.pc-inline-field {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 0.92em;
}

.pc-grow {
  flex: 1 1 auto;
  min-width: 0;
}

.pc-textarea-sm {
  min-height: 62px;
  resize: vertical;
}

.pc-textarea-lg {
  min-height: 200px;
  resize: vertical;
  font-family: monospace;
  font-size: 0.92em;
}

.pc-sheet-card.is-selected {
  border-color: var(--SmartThemeQuoteColor, #4f8cff);
}

.pc-sheet-head,
.pc-map-head,
.pc-rule-bar,
.pc-status-row,
.pc-prompt-head,
.pc-overflow-head,
.pc-footer-bar,
.pc-pager,
.pc-paste-head,
.pc-row-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.pc-pager {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px dashed rgba(255, 255, 255, 0.12);
}

.pc-check-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.pc-badges {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.pc-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 0.78em;
  background: rgba(255, 255, 255, 0.09);
  border: 1px solid rgba(255, 255, 255, 0.14);
}

.pc-badge-info {
  background: rgba(79, 140, 255, 0.18);
  border-color: rgba(79, 140, 255, 0.45);
}

.pc-badge-warn {
  background: rgba(242, 184, 75, 0.18);
  border-color: rgba(242, 184, 75, 0.45);
}

.pc-link-btn {
  background: transparent;
  border: none;
  color: var(--SmartThemeQuoteColor, #7fb3ff);
  cursor: pointer;
  font-size: 0.88em;
  padding: 4px 6px;
}

/* 桌面端数据表（静态文字浏览，点编辑才变输入框） */
.pc-table-scroll {
  overflow-x: auto;
  margin-top: 8px;
}

.pc-data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9em;
}

.pc-data-table th,
.pc-data-table td {
  border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.12));
  padding: 6px 8px;
  text-align: left;
  vertical-align: top;
}

.pc-data-table th {
  background: rgba(255, 255, 255, 0.06);
  white-space: nowrap;
}

.pc-cell-text {
  max-width: 240px;
  max-height: 4.5em;
  overflow: hidden;
  text-overflow: ellipsis;
  word-break: break-word;
  line-height: 1.45;
  cursor: text;
}

.pc-cell-input {
  width: 100%;
  min-width: 96px;
  box-sizing: border-box;
  background: rgba(0, 0, 0, 0.32);
  color: inherit;
  border: 1px solid var(--SmartThemeQuoteColor, #4f8cff);
  border-radius: 4px;
  padding: 4px 6px;
}

.pc-row-dim {
  opacity: 0.45;
}

.pc-row-editing {
  background: rgba(79, 140, 255, 0.09);
}

/* 手机端竖排数据卡片流（零横滑、零输入法误触） */
.pc-row-card-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
}

.pc-row-card {
  padding: 10px 12px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.12));
}

.pc-row-card-title {
  font-weight: 600;
  flex: 1 1 auto;
  min-width: 0;
  word-break: break-word;
}

.pc-row-card-kv {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px dashed rgba(255, 255, 255, 0.1);
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 0.88em;
}

.pc-kv-line {
  line-height: 1.4;
  word-break: break-word;
}

.pc-kv-k {
  opacity: 0.72;
}

.pc-row-edit-fields {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed rgba(79, 140, 255, 0.35);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Tab 2 响应式列映射网格：桌面三栏对照 / 手机自动单列堆叠 */
.pc-map-list {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.12));
  border-radius: 6px;
  overflow: hidden;
}

.pc-map-row {
  display: grid;
  grid-template-columns: minmax(160px, 1.1fr) 145px minmax(180px, 1.4fr);
  gap: 10px;
  align-items: start;
  padding: 8px 10px;
  border-top: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.1));
}

.pc-map-row:first-child {
  border-top: none;
}

.pc-map-row-header {
  background: rgba(255, 255, 255, 0.06);
  font-weight: 600;
  font-size: 0.88em;
}

.pc-select-full {
  width: 100%;
  box-sizing: border-box;
  margin: 0 !important;
}

.pc-val-inline {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.pc-map-target-select {
  min-width: 200px;
  margin: 0 !important;
}

.pc-status-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  margin-top: 8px;
  font-size: 0.88em;
}

.pc-mode-switch {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.pc-mode-btn {
  flex: 1 1 220px;
  padding: 10px 12px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  color: inherit;
  border: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.15));
  cursor: pointer;
  font-weight: 600;
}

.pc-mode-btn.is-active {
  background: rgba(79, 140, 255, 0.22);
  border-color: var(--SmartThemeQuoteColor, #4f8cff);
}

.pc-src-pill {
  font-weight: 600;
}

.pc-arrow {
  margin: 0 6px;
  opacity: 0.7;
}

.pc-rule-bar {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed rgba(255, 255, 255, 0.12);
}

.pc-note-details {
  margin-top: 8px;
  font-size: 0.86em;
}

.pc-note-pre,
.pc-overflow-pre {
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 180px;
  overflow-y: auto;
  padding: 8px;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.28);
  font-size: 0.88em;
  margin: 6px 0 0;
}

.pc-col-name {
  font-weight: 600;
}

.pc-col-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 3px;
}

.pc-tag {
  font-size: 0.75em;
  padding: 1px 6px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.1);
}

.pc-tag-req {
  background: rgba(235, 87, 87, 0.22);
  color: #ffb0b0;
}

.pc-tag-uniq {
  background: rgba(242, 184, 75, 0.22);
  color: #ffd88a;
}

.pc-tag-enum {
  background: rgba(79, 140, 255, 0.22);
  color: #a8ccff;
}

.pc-select-sm {
  margin: 0 !important;
  min-width: 140px;
}

.pc-mini-hint {
  font-size: 0.8em;
  color: #a8ccff;
}

.pc-combine-wrap {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.pc-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.08);
  font-size: 0.86em;
}

.pc-joiner-input {
  width: 48px !important;
  text-align: center;
  margin: 0 !important;
}

.pc-op-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
  max-height: 240px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.pc-op-item {
  padding: 8px 10px;
  border-radius: 6px;
  border-left: 3px solid rgba(255, 255, 255, 0.2);
  background: rgba(0, 0, 0, 0.2);
  font-size: 0.88em;
}

.pc-op-ok {
  border-left-color: #4cc38a;
}

.pc-op-warn {
  border-left-color: #f2b84b;
}

.pc-op-err {
  border-left-color: #eb5757;
}

.pc-op-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.pc-op-data {
  margin-top: 4px;
  opacity: 0.9;
  line-height: 1.45;
  word-break: break-word;
}

.pc-ok {
  color: #5cd69a;
}

.pc-warn,
.pc-warn-line {
  color: #ffd07a;
}

.pc-err,
.pc-err-line {
  color: #ff9494;
}

.pc-err-line,
.pc-warn-line {
  margin-top: 3px;
}

.pc-overflow-card {
  border-color: rgba(79, 140, 255, 0.4);
}

.pc-receipt-ok {
  border-color: rgba(76, 195, 138, 0.55);
}

.pc-receipt-err {
  border-color: rgba(235, 87, 87, 0.55);
}

.pc-receipt-list {
  margin: 6px 0 0 18px;
  padding: 0;
  font-size: 0.88em;
}

.pc-lib-card {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.pc-lib-name {
  font-weight: 700;
  font-size: 1.05em;
}

.pc-lib-summary,
.pc-lib-note {
  margin-top: 4px;
  font-size: 0.9em;
  word-break: break-word;
}

.pc-lib-actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.pc-mt-sm {
  margin-top: 8px;
}

.pc-mb-xs {
  margin-bottom: 4px;
}

.pc-mb-sm {
  margin-bottom: 8px;
}

.pc-pad-sm {
  padding: 8px 0 2px;
}

/* ==================== 手机端专项适配（≤768px：全屏抽屉 + 大触控区 + 单列映射） ==================== */
@media (max-width: 768px) {
  .pc-overlay {
    padding: 0;
    align-items: stretch;
  }

  .pc-modal {
    width: 100vw;
    height: 100dvh;
    max-height: 100dvh;
    border-radius: 0;
    border: none;
    box-shadow: none;
  }

  .pc-header {
    padding: calc(10px + env(safe-area-inset-top, 0px)) 12px 10px;
  }

  .pc-close-btn {
    min-width: 42px;
    min-height: 42px;
    font-size: 1.05em;
  }

  .pc-tabs {
    padding: 6px 8px 0;
    gap: 2px;
  }

  .pc-tab {
    flex: 1 1 0;
    text-align: center;
    padding: 10px 6px;
    font-size: 0.9em;
  }

  .pc-body {
    padding: 10px 10px calc(18px + env(safe-area-inset-bottom, 0px));
    gap: 10px;
  }

  .pc-card {
    padding: 10px 11px;
  }

  .pc-form-grid,
  .pc-grid-3 {
    grid-template-columns: 1fr;
  }

  /* 防止 iOS WKWebView 聚焦输入控件时自动缩放页面 */
  .pc-modal input[type="text"],
  .pc-modal input[type="number"],
  .pc-modal select,
  .pc-modal textarea {
    font-size: 16px !important;
    min-height: 40px;
  }

  .pc-modal .menu_button,
  .pc-mode-btn {
    min-height: 42px;
    padding: 8px 12px;
  }

  .pc-mini-btn,
  .pc-touch-btn {
    min-height: 36px;
    padding: 6px 10px;
  }

  .pc-checkbox {
    width: 22px;
    height: 22px;
  }

  .pc-map-head {
    flex-direction: column;
    align-items: stretch;
  }

  .pc-map-target-select {
    width: 100%;
    min-width: 0;
  }

  .pc-map-row-header {
    display: none;
  }

  .pc-map-row {
    grid-template-columns: 1fr;
    gap: 8px;
    padding: 10px;
  }

  .pc-sticky-footer {
    position: sticky;
    bottom: 0;
    z-index: 5;
    padding: 10px 12px calc(10px + env(safe-area-inset-bottom, 0px));
    margin: 4px -10px -10px;
    background: var(--SmartThemeBlurTintColor, #1c1f26);
    border-top: 1px solid var(--SmartThemeBorderColor, rgba(255, 255, 255, 0.18));
  }

  .pc-footer-hint {
    flex: 1 1 100%;
    font-size: 0.84em;
  }

  .pc-lib-actions {
    width: 100%;
  }

  .pc-lib-actions .menu_button {
    flex: 1 1 auto;
    text-align: center;
  }
}
";
  const __factories = {
  "src/host-env.js": function(exports, __require) {
/**
 * src/host-env.js
 * 统一宿主窗口、文档与运行模式桥接层。
 * 同时兼容：
 * 1. SillyTavern / TauriTavern 标准前端扩展模式（运行在宿主主窗口 window）
 * 2. 酒馆助手 / Tavern Helper（JS-Slash-Runner）脚本模式（运行在 script iframe，宿主为 window.parent）
 */

const INSTANCE_FLAG = '__ST_PROTAGONIST_CARRYOVER_LOADED__';
const INLINE_STYLE_ID = 'pc-carryover-inline-style';

let forcedRuntimeMode = null; // 'extension' | 'tavern-helper' | null

/** 由打包入口或测试显式指定运行模式 */
function setRuntimeMode(mode) {
  forcedRuntimeMode = mode === 'tavern-helper' || mode === 'extension' ? mode : null;
}

/** 检测当前运行模式：'tavern-helper'（iframe 脚本）或 'extension'（主窗口扩展） */
function detectRuntimeMode() {
  if (forcedRuntimeMode) return forcedRuntimeMode;
  try {
    if (typeof window !== 'undefined' && typeof window.parent !== 'undefined' && window.parent !== window) {
      // 确认能访问父窗口 document（同源酒馆助手 script iframe）
      void window.parent.document;
      return 'tavern-helper';
    }
  } catch {
    return 'tavern-helper';
  }
  return 'extension';
}

function isTavernHelperIframeMode() {
  return detectRuntimeMode() === 'tavern-helper';
}

/** 获取酒馆/TauriTavern 主窗口引用（iframe 模式下为 window.parent） */
function getHostWindow() {
  if (typeof window === 'undefined') return globalThis;
  if (isTavernHelperIframeMode()) {
    try {
      if (window.parent && window.parent !== window) {
        return window.parent;
      }
    } catch {
      return window;
    }
  }
  return window;
}

/** 获取酒馆/TauriTavern 主文档引用（确保弹窗、样式、魔法棒入口挂载到可见宿主页面） */
function getHostDocument() {
  try {
    const win = getHostWindow();
    if (win?.document) return win.document;
  } catch {
    // ignore
  }
  return typeof document !== 'undefined' ? document : null;
}

/** 获取 SillyTavern 全局对象 */
function getSillyTavernGlobal() {
  const hostWin = getHostWindow();
  return hostWin?.SillyTavern || globalThis.SillyTavern || null;
}

/** 安全获取 SillyTavern.getContext() */
function getSillyTavernContextSafe() {
  try {
    const st = getSillyTavernGlobal();
    if (typeof st?.getContext === 'function') {
      return st.getContext();
    }
  } catch (err) {
