  const chat = Array.isArray(stContext?.chat) ? stContext.chat : [];
  let aiFloorCount = 0;
  let lastAiIndex = -1;
  for (let i = 0; i < chat.length; i += 1) {
    const msg = chat[i];
    if (msg && !msg.is_user && !msg.is_system) {
      aiFloorCount += 1;
      lastAiIndex = i;
    }
