      ok: false,
      error: '写入计划中仍有未处理的红色规则错误，已拦截写入以保护目标数据库。',
      results: [],
      succeeded: 0,
      failed: 0,
      skipped: 0,
      refreshed: false,
    };
  }

  const results = [];
  let succeeded = 0;
  let failed = 0;
  let skipped = 0;

  for (const op of compiledPlan.operations) {
    if (op.action === 'skip') {
      skipped += 1;
